const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cats=['Weddings','Pre-Wedding','Birthdays','Portraits','Engagements','Events','Maternity','Fashion & Creative'];
const samples=[['6500','Together in the light','Pre-Wedding'],['4081','A portrait in light','Portraits'],['7872','Awaiting a little miracle','Maternity'],['4059','A portrait in light','Portraits'],['4699','The beginning of forever','Weddings'],['6578','Light and imagination','Portraits']].map((p,i)=>({id:'preview-'+i,url:'/assets/msr-'+p[0]+'.jpg',title:p[1],category:p[2],description:p[1]+' — Imagica Portraits',featured:true,published:true}));
let photos=[],events=[],settings={},filter='All',visible=[],lightIndex=0,session=null;

const connected=()=>true;
const toast=m=>{$('#toast').textContent=m;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',6000)};
function safeUrl(v){try{let u=new URL(v,location.origin);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
async function api(path,opts={}){const r=await fetch('/api'+path,{...opts,credentials:'same-origin',headers:{...(opts.body instanceof File?{}:{'Content-Type':'application/json'}),'X-Imagica-Request':'studio',...opts.headers}});if(!r.ok){const e=await r.json().catch(()=>({}));throw Error(e.message||'Request failed ('+r.status+')')}return r.status===204?null:r.json().catch(()=>null)}
const options=(selected='')=>cats.map(c=>`<option ${c===selected?'selected':''}>${c}</option>`).join('');
const booking=()=>settings.phone?`https://wa.me/${settings.phone.replace(/\D/g,'')}`:'/contact/';
const cta=()=>`<section class="cta"><span class="script">Your story deserves to be remembered</span><h2>Let’s create something<br><em>beautiful together.</em></h2><a class="button" href="/contact/">Let’s plan your shoot ↗</a></section>`;
const head=(tag,title,desc)=>`<div class="page-head"><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${desc}</p></div>`;
function photoGrid(items){return items.map(p=>`<button class="photo" data-photo="${esc(p.id)}" aria-label="View ${esc(p.title)}"><img src="${esc(safeUrl(p.url))}" alt="${esc(p.description||p.title)}" loading="lazy"><span>${esc(p.title)} <span class="eyebrow">${esc(p.category)}</span></span></button>`).join('')}
function bindHomeBanners(){let current=0;const slides=[...document.querySelectorAll('[data-banner-frame]')];if(!slides.length)return;const show=n=>{current=(n+slides.length)%slides.length;slides.forEach((s,i)=>s.hidden=i!==current);document.querySelectorAll('[data-banner-to]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===current)))};document.querySelectorAll('[data-banner-to]').forEach(b=>b.onclick=()=>show(Number(b.dataset.bannerTo)));document.querySelectorAll('[data-banner-step]').forEach(b=>b.onclick=()=>show(current+Number(b.dataset.bannerStep)))}
function render(){const path=location.pathname.replace(/\/$/,'')||'/';document.title=({ '/':'Home','/about':'About','/gallery':'Gallery','/events':'Events','/contact':'Contact','/admin':'Studio admin'}[path]||'Page not found')+' | Imagica Portraits';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.pathname.replace(/\/$/,'')===path));$('#main').innerHTML=path==='/'?home():path==='/about'?about():path==='/gallery'?gallery():path==='/events'?eventsPage():path==='/contact'?contact():path==='/admin'?admin():head('404','A frame <em>out of place.</em>','This page could not be found. <a href="/">Return home ↗</a>');if(path==='/gallery')updateGallery();renderFooter();bind();$('#floating').href=booking();$('#floating').textContent=settings.phone?'WhatsApp ↗':'Let’s talk ↗'}
function updateGallery(){visible=photos.filter(p=>filter==='All'||p.category===filter);$('#gallery-grid').innerHTML=visible.length?photoGrid(visible):'<div class="empty editorial-empty"><h3>This chapter is still being written.</h3><p>New photographs will appear here soon.</p><a class="text-link" href="/contact/">Plan your own story ↗</a></div>';document.querySelectorAll('.filter').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter))}
function openPhoto(id){visible=photos.filter(p=>location.pathname.includes('gallery')?(filter==='All'||p.category===filter):true);lightIndex=visible.findIndex(p=>p.id===id);showLight();$('#lightbox').showModal()}
function showLight(){const p=visible[lightIndex];if(!p)return;$('#lightbox-img').src=p.url;$('#lightbox-img').alt=p.description||p.title;$('figcaption').textContent=p.title+' · '+p.category}
function bind(){bindAdminLogin();bindHomeBanners();bindEventFilters();document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;updateGallery()});$('#main').onclick=e=>{const b=e.target.closest('[data-photo]');if(b)openPhoto(b.dataset.photo)};const f=$('#inquiry');if(f)f.onsubmit=e=>{e.preventDefault();if(!settings.phone)return toast('The studio has not configured its WhatsApp number yet.');const d=new FormData(f);location.href=booking()+'?text='+encodeURIComponent(`Hello Imagica Portraits!\nName: ${d.get('name')}\nPhone: ${d.get('phone')}\nShoot: ${d.get('type')}\nPreferred date: ${d.get('date')}\n${d.get('message')}`)};if($('#admin-content'))loadAdmin().catch(e=>toast(e.message))}
function admin(){return head('Studio administration','A space for <em>your stories.</em>','Manage the photographs and details your visitors see.')+`<div class="admin">${session?.admin?'<button id="logout" class="button small">Sign out</button><div id="admin-content"><p>Loading your studio…</p></div>':`<form id="admin-login" class="panel" style="max-width:540px;margin:auto"><span class="eyebrow">Imagica Portraits</span><h3>Welcome to your studio</h3><p>Sign in with your administrator email and password.</p><label>Email address<input name="email" type="email" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><p id="login-error" role="alert"></p><button class="button" type="submit">Sign in ↗</button></form>`}<aside class="admin-help"><span class="eyebrow">Your studio workflow</span><h3>Upload once. Share with everyone.</h3><ol><li>Sign in with your administrator email and password.</li><li>Choose <strong>Upload photographs</strong>, then select the occasion.</li><li>Add a title and description. Select JPG, PNG or WebP photos up to 10 MB each.</li><li>Keep <strong>Publish to public gallery</strong> checked to display them for visitors.</li><li>Use <strong>Gallery manager</strong> to edit, replace, feature or unpublish photographs. Deleted items move to Trash.</li><li>Manage event dates and images in <strong>Events</strong>, and contact details in <strong>Site settings</strong>.</li></ol></aside></div>`}
function bindAdminLogin(){const f=$('#admin-login');if(f)f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button');b.disabled=true;$('#login-error').textContent='';try{const d=new FormData(f);session=await api('/auth/login',{method:'POST',body:JSON.stringify({email:d.get('email'),password:d.get('password')})});f.reset();render()}catch(err){$('#login-error').textContent=err.message}finally{b.disabled=false}};const logout=$('#logout');if(logout)logout.onclick=async()=>{try{await api('/auth/logout',{method:'POST'});session=null;render()}catch(err){toast(err.message)}}}
async function upload(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024||!file.size)throw Error('Use JPG, PNG or WebP images up to 10 MB.');const key=crypto.randomUUID()+'.'+({'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type]);await api('/storage/v1/object/photos/'+key,{method:'POST',body:file,headers:{'Content-Type':file.type}});return location.origin+'/media/'+key}
async function loadAdmin(){const owner=await api('/rest/v1/admin_users?select=user_id');if(!owner.length){$('#admin-content').innerHTML='<p class="notice">This account does not have studio administrator access.</p>';return}const all=await api('/rest/v1/photos?select=*&order=created_at.desc'),ev=await api('/rest/v1/events?select=*&order=date.asc'),trash=await api('/admin/trash');$('#admin-content').innerHTML=`<div class="admin-tabs"><a href="#upload-panel" class="text-link">Upload photographs</a><a href="#manage-photos" class="text-link">Gallery manager</a><a href="#event-panel" class="text-link">Events</a><a href="#settings-panel" class="text-link">Site settings</a><a href="#trash-panel" class="text-link">Trash</a></div><form id="upload-form" class="panel"><h3 id="upload-panel">Publish a new collection</h3><label>Which category do these photographs belong to?<select name="category" required><option value="">Choose an occasion</option>${options()}</select></label><label>Collection / image title<input name="title" required maxlength="160"></label><label>Description / alt text<textarea name="description" required maxlength="1000"></textarea></label><label>Photographs (JPG, PNG, WebP · 10 MB each)<input type="file" id="photo-files" accept="image/jpeg,image/png,image/webp" multiple required></label><div class="preview" id="upload-preview"></div><label><input style="width:auto;display:inline" type="checkbox" name="featured"> Feature on homepage</label><label><input style="width:auto;display:inline" type="checkbox" name="published" checked> Publish to public gallery</label><progress id="upload-progress" value="0" max="100"></progress><button class="button">Upload photographs ↗</button></form><div class="panel"><h3 id="manage-photos">Gallery manager</h3><div class="admin-list">${all.map(p=>`<article><img src="${esc(p.url)}" alt="${esc(p.title)}" loading="lazy"><form data-edit="${p.id}"><label>Title<input name="title" value="${esc(p.title)}" required maxlength="160"></label><label>Description<textarea name="description" maxlength="1000">${esc(p.description)}</textarea></label><label>Category<select name="category">${options(p.category)}</select></label><label><input style="width:auto;display:inline" name="featured" type="checkbox" ${p.featured?'checked':''}> Featured</label><label><input style="width:auto;display:inline" name="published" type="checkbox" ${p.published?'checked':''}> Published</label><label>Replace image<input name="replacement" type="file" accept="image/jpeg,image/png,image/webp"></label><button class="button small">Save</button> <button type="button" class="danger" data-delete-photo="${p.id}">Delete</button></form></article>`).join('')||'<p>No uploads yet.</p>'}</div></div><form id="event-form" class="panel"><h3 id="event-panel">Create / edit an event</h3><input type="hidden" name="id"><label>Event title<input name="title" required maxlength="160"></label><div class="form-grid"><label>Date and time (India)<input name="date" type="datetime-local" required></label><label>Location<input name="location" required maxlength="300"></label></div><label>Description<textarea name="description" required maxlength="3000"></textarea></label><label>Cover image<input name="cover" type="file" accept="image/jpeg,image/png,image/webp"></label><label>Additional event images<input name="images" type="file" multiple accept="image/jpeg,image/png,image/webp"></label><div id="event-existing-images"></div><label><input style="width:auto;display:inline" name="published" type="checkbox" checked> Published</label><button class="button">Save event</button> <button type="reset" class="button outline">Clear</button><p class="sample">Upcoming / completed status is calculated from the event date.</p></form><div class="panel">${ev.map(e=>`<p>${esc(e.title)} · ${esc(e.date)} · ${e.published?'Published':'Draft'} <button data-edit-event="${e.id}">Edit</button> <button class="danger" data-delete-event="${e.id}">Delete</button></p>`).join('')||'No events yet.'}</div><form class="panel" id="settings-form"><h3 id="settings-panel">Contact & site settings</h3>${[['phone','WhatsApp number (country code, digits only)'],['email','Email'],['instagram','Instagram URL'],['location','Business location'],['testimonial','Client testimonial (publish only with consent)'],['testimonialName','Client attribution'],['photographerName','Photographer / studio team name'],['studioBio','About page studio biography']].map(([k,label])=>`<label>${label}<input name="${k}" value="${esc(settings[k]||'')}" maxlength="${k==='studioBio'?3000:1000}" ${k==='email'?'type="email"':k==='instagram'?'type="url"':''}></label>`).join('')}<button class="button">Save settings</button></form><div class="panel"><h3 id="trash-panel">Trash</h3><p>Deleted items are hidden from visitors. Restore an item as a draft, then publish it when ready.</p>${[...trash.photos.map(p=>({...p,type:"photos"})),...trash.events.map(p=>({...p,type:"events"}))].map(p=>`<p>${esc(p.title)} <button class="button small" data-restore="${p.id}" data-kind="${p.type}">Restore draft</button></p>`).join("")||"<p>Trash is empty.</p>"}</div>`;
document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{try{await api('/rest/v1/'+b.dataset.kind+'?id=eq.'+b.dataset.restore,{method:'PATCH',body:JSON.stringify({restore:true})});await loadData();await loadAdmin();toast('Restored as a draft.')}catch(e){toast(e.message)}});
$('#photo-files').onchange=e=>{const box=$('#upload-preview');box.querySelectorAll('img').forEach(i=>URL.revokeObjectURL(i.src));box.innerHTML='';[...e.target.files].forEach(f=>{const i=document.createElement('img');i.src=URL.createObjectURL(f);i.alt=f.name;box.append(i)})};
async function action(form,fn){const b=form.querySelector('button');b.disabled=true;try{await fn();toast('Saved successfully. Items marked Published are visible to visitors.');await loadData();await loadAdmin()}catch(e){toast(e.message)}finally{b.disabled=false}}
$('#upload-form').onsubmit=e=>{e.preventDefault();action(e.target,async()=>{const d=new FormData(e.target),files=[...$('#photo-files').files];for(let i=0;i<files.length;i++){const url=await upload(files[i]);await api('/rest/v1/photos',{method:'POST',body:JSON.stringify({url,title:d.get('title')+(files.length>1?' · '+(i+1):''),description:d.get('description'),category:d.get('category'),featured:d.has('featured'),published:d.has('published')})});$('#upload-progress').value=(i+1)/files.length*100}})};
document.querySelectorAll('[data-edit]').forEach(f=>f.onsubmit=e=>{e.preventDefault();action(f,async()=>{const d=new FormData(f),data={title:d.get('title'),description:d.get('description'),category:d.get('category'),featured:d.has('featured'),published:d.has('published')};if(d.get('replacement').size)data.url=await upload(d.get('replacement'));await api('/rest/v1/photos?id=eq.'+f.dataset.edit,{method:'PATCH',body:JSON.stringify(data)})})});
document.querySelectorAll('[data-delete-photo]').forEach(b=>b.onclick=async()=>{try{const p=all.find(p=>p.id===b.dataset.deletePhoto);await api('/rest/v1/photos?id=eq.'+p.id,{method:'DELETE'});await api('/storage/v1/object/photos',{method:'DELETE',body:JSON.stringify({prefixes:[p.url.split('/').pop()]})});await loadData();await loadAdmin();toast('Photograph moved to Trash.')}catch(e){toast(e.message)}});
document.querySelectorAll('[data-edit-event]').forEach(b=>b.onclick=()=>{const item=ev.find(e=>e.id===b.dataset.editEvent),f=$('#event-form');for(const k of ['id','title','location','description'])f.elements[k].value=item[k];f.elements.date.value=new Date(new Date(item.date).getTime()+19800000).toISOString().slice(0,16);f.elements.published.checked=item.published;$('#event-existing-images').innerHTML=(item.cover_url?`<label><input type="checkbox" name="removeCover" style="width:auto;display:inline"> Remove current cover</label>`:'')+(item.images||[]).map(u=>`<label><img src="${esc(u)}" alt="Event photograph" width="100" loading="lazy"><input type="checkbox" name="removeImage" value="${esc(u)}" style="width:auto;display:inline"> Remove this photo</label>`).join('');f.scrollIntoView({behavior:'smooth'})});
document.querySelectorAll('[data-delete-event]').forEach(b=>b.onclick=async()=>{try{await api('/rest/v1/events?id=eq.'+b.dataset.deleteEvent,{method:'DELETE'});await loadData();await loadAdmin();toast('Event moved to Trash.')}catch(e){toast(e.message)}});
$('#event-form').onreset=()=>{$('#event-existing-images').innerHTML=''};
$('#event-form').onsubmit=e=>{e.preventDefault();action(e.target,async()=>{const d=new FormData(e.target),id=d.get('id'),old=ev.find(e=>e.id===id),data={title:d.get('title'),date:new Date(d.get('date')+'+05:30').toISOString(),location:d.get('location'),description:d.get('description'),published:d.has('published'),cover_url:d.has('removeCover')?null:old?.cover_url||null,images:(old?.images||[]).filter(u=>!d.getAll('removeImage').includes(u))};if(d.get('cover').size)data.cover_url=await upload(d.get('cover'));for(const file of d.getAll('images'))if(file.size)data.images.push(await upload(file));await api('/rest/v1/events'+(id?'?id=eq.'+id:''),{method:id?'PATCH':'POST',body:JSON.stringify(data)})})};
$('#settings-form').onsubmit=e=>{e.preventDefault();action(e.target,async()=>{const data=Object.fromEntries(new FormData(e.target));if(data.phone&&!/^\d{8,15}$/.test(data.phone))throw Error('Enter 8–15 digits with country code for WhatsApp.');await api('/rest/v1/settings',{method:'POST',headers:{Prefer:'resolution=merge-duplicates'},body:JSON.stringify({id:1,data})})})}}
async function loadData(){const [p,e,s,me]=await Promise.all([api('/rest/v1/photos?select=*&published=eq.true&order=created_at.desc'),api('/rest/v1/events?select=*&published=eq.true&order=date.asc'),api('/rest/v1/settings?select=data&id=eq.1'),location.pathname.startsWith('/admin')?api('/me'):Promise.resolve(null)]);photos=p;events=e;settings=s[0]?.data||{};if(me)session=me}
$('#menu').onclick=()=>{const open=$('nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open)};$('#year').textContent=new Date().getFullYear();$('#close-lightbox').onclick=()=>$('#lightbox').close();$('#prev').onclick=()=>{lightIndex=(lightIndex-1+visible.length)%visible.length;showLight()};$('#next').onclick=()=>{lightIndex=(lightIndex+1)%visible.length;showLight()};document.addEventListener('keydown',e=>{if($('#lightbox').open){if(e.key==='ArrowRight')$('#next').click();if(e.key==='ArrowLeft')$('#prev').click()}});filter=new URLSearchParams(location.search).get('category')||'All';if(!location.pathname.startsWith('/admin')){photos=[];render()}loadData().then(render).catch(e=>{photos=[];render();toast('Content could not be loaded. Please try again later.')});
